    { title: 'Mars Rovers', icon: '🤖', url: '/learn/aerospace#rovers', desc: 'Discover how NASA rovers explore Mars using orbital mechanics and robotics.', keywords: ['Mars', 'NASA', 'rovers', 'exploration'] },
    { title: 'James Webb Telescope', icon: '🔭', url: '/learn/aerospace', desc: 'Explore how the James Webb Space Telescope observes the universe from L2 point.', keywords: ['James Webb', 'NASA', 'telescope', 'astronomy'] },
    { title: 'Apollo Moon Missions', icon: '🌙', url: '/learn/aerospace#nasa', desc: 'Learn how NASA used Newton\'s laws to land humans on the Moon.', keywords: ['Apollo', 'NASA', 'Moon', 'missions'] },
    { title: 'GPS Satellites', icon: '📡', url: '/satellites', desc: 'Understand how GPS satellites in MEO enable global navigation.', keywords: ['GPS', 'satellites', 'navigation', 'MEO'] }
  ],
  'newton': [
    { title: 'Newton\'s First Law', icon: '⚖️', url: '/learn/newton', desc: 'Learn about inertia and why objects in motion stay in motion.', keywords: ['Newton', 'first law', 'inertia', 'physics'] },
    { title: 'Newton\'s Second Law', icon: '🚀', url: '/learn/newton', desc: 'Discover F=ma and how it explains rocket acceleration.', keywords: ['Newton', 'second law', 'force', 'acceleration'] },
    { title: 'Newton\'s Third Law', icon: '💥', url: '/learn/newton', desc: 'Understand action-reaction and how rockets propel forward.', keywords: ['Newton', 'third law', 'action-reaction', 'rockets'] },
    { title: 'Law of Universal Gravitation', icon: '🌍', url: '/formulas-library', desc: 'Explore how gravity keeps satellites in orbit around Earth.', keywords: ['Newton', 'gravity', 'gravitation', 'orbits'] },
    { title: 'Newton and Orbits', icon: '🛸', url: '/simulator', desc: 'See how Newton\'s laws make satellite orbits possible.', keywords: ['Newton', 'orbits', 'satellites', 'physics'] }
  ],
  'quantum-physics': [
    { title: 'Quantum Mechanics Basics', icon: '⚛️', url: '/research', desc: 'Introduction to quantum physics and its role in space technology.', keywords: ['quantum', 'physics', 'mechanics', 'science'] },
    { title: 'Quantum Entanglement', icon: '🔗', url: '/research', desc: 'Learn about quantum entanglement and its applications in space communication.', keywords: ['quantum', 'entanglement', 'physics', 'communication'] },
    { title: 'Quantum Computing in Space', icon: '💻', url: '/research', desc: 'Discover how quantum computing advances space exploration.', keywords: ['quantum', 'computing', 'space', 'technology'] },
    { title: 'Quantum Sensors', icon: '📊', url: '/research', desc: 'Explore quantum sensors used in satellite navigation.', keywords: ['quantum', 'sensors', 'satellites', 'navigation'] }
  ],
  'astrophysics': [
    { title: 'Black Holes', icon: '🕳️', url: '/research', desc: 'Learn about black holes, event horizons, and gravitational physics.', keywords: ['black holes', 'astrophysics', 'gravity', 'space'] },
    { title: 'Star Formation', icon: '⭐', url: '/research', desc: 'Discover how stars are born from gas clouds in space.', keywords: ['stars', 'formation', 'astrophysics', 'space'] },
    { title: 'Dark Matter', icon: '🌌', url: '/research', desc: 'Explore the mysterious dark matter that shapes the universe.', keywords: ['dark matter', 'astrophysics', 'universe', 'physics'] },
    { title: 'Cosmic Microwave Background', icon: '🌠', url: '/research', desc: 'Learn about the oldest light in the universe and the Big Bang.', keywords: ['CMB', 'astrophysics', 'Big Bang', 'universe'] },
    { title: 'Exoplanets', icon: '🪐', url: '/research', desc: 'Discover planets orbiting other stars and how we detect them.', keywords: ['exoplanets', 'astrophysics', 'planets', 'space'] }
  ],
  'orbital-mechanics': [
    { title: 'Kepler\'s Laws', icon: '🌍', url: '/formulas-library', desc: 'Learn Kepler\'s three laws that describe planetary motion.', keywords: ['Kepler', 'laws', 'orbital mechanics', 'planets'] },
    { title: 'Escape Velocity', icon: '🚀', url: '/formulas-library', desc: 'Understand the speed needed to escape Earth\'s gravity.', keywords: ['escape velocity', 'gravity', 'rockets', 'physics'] },
    { title: 'Hohmann Transfer', icon: '🔄', url: '/simulator', desc: 'Learn the most efficient way to transfer between orbits.', keywords: ['Hohmann', 'transfer', 'orbits', 'spacecraft'] },
    { title: 'Lagrange Points', icon: '⚖️', url: '/learn/aerospace', desc: 'Discover the special points where gravity balances perfectly.', keywords: ['Lagrange', 'points', 'gravity', 'orbits'] }
  ]
};

// Select random category and topic
const category = categories[Math.floor(Math.random() * categories.length)];
const topicList = topics[category];
const selectedTopic = topicList[Math.floor(Math.random() * topicList.length)];

// Get today's date
const today = new Date().toISOString().split('T')[0];

// Generate ID
const id = `${category}-${today}`;

return {
  json: {
    id,
    date: today,
    title: selectedTopic.title,
    icon: selectedTopic.icon,
    category,
    description: selectedTopic.desc,
    learnMoreUrl: selectedTopic.url,
    keywords: selectedTopic.keywords
  }
};
